const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo((res) => resolve(res), (err) => reject(err));
  });
}

function s2MaskClouds(img) {
  // Mask clouds, cloud shadows, and snow/ice using SCL
  const scl = img.select('SCL');
  const cloud = scl.eq(3) // shadow
    .or(scl.eq(7)) // cloud low prob
    .or(scl.eq(8)) // cloud med prob
    .or(scl.eq(9)) // cloud high prob
    .or(scl.eq(10)); // cirrus
  const snow = scl.eq(11);
  const valid = cloud.not().and(snow.not());
  return img.updateMask(valid);
}

function s2CloudFrac(img, region, scale) {
  const scl = img.select('SCL');
  const cloud = scl.eq(3)
    .or(scl.eq(7))
    .or(scl.eq(8))
    .or(scl.eq(9))
    .or(scl.eq(10));
  const ones = ee.Image(1).updateMask(img.select('B3').mask());
  const cloudCount = ones.updateMask(cloud).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9,
  }).values().get(0);
  const totalCount = ones.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9,
  }).values().get(0);
  return ee.Number(cloudCount).divide(ee.Number(totalCount));
}

function lsScaleSR(img) {
  const scale = ee.Image.constant(0.0000275);
  const offset = ee.Image.constant(-0.2);
  const scaled = img.select(['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'])
    .multiply(scale).add(offset)
    .rename(['blue','green','red','nir','swir1','swir2']);
  return img.addBands(scaled, null, true);
}

function lsMaskClouds(img) {
  // QA_PIXEL bits: 1 Dilated Cloud, 3 Cloud, 4 Cloud Shadow, 5 Snow
  const qa = img.select('QA_PIXEL');
  const dilated = qa.bitwiseAnd(1 << 1).neq(0);
  const cloud = qa.bitwiseAnd(1 << 3).neq(0);
  const cloudShadow = qa.bitwiseAnd(1 << 4).neq(0);
  const snow = qa.bitwiseAnd(1 << 5).neq(0);
  const mask = dilated.or(cloud).or(cloudShadow).or(snow).not();
  return img.updateMask(mask);
}

function lsCloudFrac(img, region, scale) {
  const qa = img.select('QA_PIXEL');
  const dilated = qa.bitwiseAnd(1 << 1).neq(0);
  const cloud = qa.bitwiseAnd(1 << 3).neq(0);
  const cloudShadow = qa.bitwiseAnd(1 << 4).neq(0);
  const snow = qa.bitwiseAnd(1 << 5).neq(0);
  const cld = dilated.or(cloud).or(cloudShadow).or(snow);
  const ones = ee.Image(1).updateMask(img.select('SR_B3').mask());
  const cloudCount = ones.updateMask(cld).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9,
  }).values().get(0);
  const totalCount = ones.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9,
  }).values().get(0);
  return ee.Number(cloudCount).divide(ee.Number(totalCount));
}

function computeNDWI(img, sensor) {
  if (sensor === 'S2') {
    const green = img.select('B3');
    const nir = img.select('B8');
    const swir1 = img.select('B11');
    const ndwi = green.subtract(nir).divide(green.add(nir)).rename('ndwi');
    const ndsi = green.subtract(swir1).divide(green.add(swir1)).rename('ndsi');
    return img.addBands([ndwi, ndsi]);
  } else {
    const green = img.select('green');
    const nir = img.select('nir');
    const swir1 = img.select('swir1');
    const ndwi = green.subtract(nir).divide(green.add(nir)).rename('ndwi');
    const ndsi = green.subtract(swir1).divide(green.add(swir1)).rename('ndsi');
    return img.addBands([ndwi, ndsi]);
  }
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const lat = 35.879797;
    const lon = 86.428836;
    const point = ee.Geometry.Point([lon, lat]);
    const region = point.buffer(50000).bounds(1);
    const targetDate = '2024-08-11';
    const tightStart = '2024-08-11';
    const tightEnd = '2024-08-12';
    const wideStart = '2024-08-05';
    const wideEnd = '2024-08-17';
    const lsStart = '2024-08-01';
    const lsEnd = '2024-08-21';
    const countScale = 120; // meters for counting and cloud fraction (balanced)
    const vecScale = 120; // vectorization scale
    const minLakeArea = 100000; // m^2 (0.1 km^2) to avoid tiny patches

    console.log('Target date: 2024-08-11');

    // 2. Sentinel-2 acquisition and checks
    let s2Tight = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(tightStart, tightEnd);
    let s2TightCount = await getInfoAsync(s2Tight.size());
    console.log(`S2 images (tight): ${s2TightCount}`);

    let s2Sel = null;
    let sensorUsed = null;
    let selCloudFrac = null;
    let selDateStr = null;
    if (s2TightCount > 0) {
      // Compute cloud fraction per image and select best
      s2Tight = s2Tight.map(img => {
        const cf = s2CloudFrac(img, region, countScale);
        return img.set('cloudFrac', cf).set('imgDate', img.date().format('YYYY-MM-dd'));
      });
      s2Sel = s2Tight.sort('cloudFrac').first();
      sensorUsed = 'S2';
      selCloudFrac = await getInfoAsync(ee.Number(ee.Image(s2Sel).get('cloudFrac')));
      selDateStr = await getInfoAsync(ee.String(ee.Image(s2Sel).get('imgDate')));
    } else {
      let s2Wide = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(wideStart, wideEnd);
      const s2WideCount = await getInfoAsync(s2Wide.size());
      console.log(`S2 images (±6d): ${s2WideCount}`);
      if (s2WideCount > 0) {
        s2Wide = s2Wide.map(img => {
          const cf = s2CloudFrac(img, region, countScale);
          return img.set('cloudFrac', cf).set('imgDate', img.date().format('YYYY-MM-dd'));
        });
        s2Sel = s2Wide.sort('cloudFrac').first();
        sensorUsed = 'S2';
        selCloudFrac = await getInfoAsync(ee.Number(ee.Image(s2Sel).get('cloudFrac')));
        selDateStr = await getInfoAsync(ee.String(ee.Image(s2Sel).get('imgDate')));
      } else {
        // Landsat fallback
        let l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
          .filterBounds(region).filterDate(lsStart, lsEnd);
        let l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
          .filterBounds(region).filterDate(lsStart, lsEnd);
        let lsCol = l8.merge(l9);
        const lsCount = await getInfoAsync(lsCol.size());
        console.log(`Landsat (±10d): ${lsCount}`);
        if (lsCount === 0) {
          console.log('No images available in all attempts.');
          console.log('C1');
          return;
        }
        lsCol = lsCol.map(lsScaleSR).map(img => {
          const cf = lsCloudFrac(img, region, countScale);
          return img.set('cloudFrac', cf).set('imgDate', img.date().format('YYYY-MM-dd'));
        });
        s2Sel = lsCol.sort('cloudFrac').first();
        sensorUsed = 'LS';
        selCloudFrac = await getInfoAsync(ee.Number(ee.Image(s2Sel).get('cloudFrac')));
        selDateStr = await getInfoAsync(ee.String(ee.Image(s2Sel).get('imgDate')));
      }
    }

    // 3. Processing
    let imgMasked, imgForBands;
    if (sensorUsed === 'S2') {
      imgMasked = s2MaskClouds(ee.Image(s2Sel));
      imgForBands = imgMasked;
    } else if (sensorUsed === 'LS') {
      imgMasked = lsMaskClouds(ee.Image(s2Sel));
      imgForBands = imgMasked;
    } else {
      console.log('Unexpected sensor selection.');
      console.log('C3');
      return;
    }

    // Valid pixel count after masking (use green band presence)
    const validOnes = ee.Image(1).updateMask(
      sensorUsed === 'S2' ? imgForBands.select('B3').mask() : imgForBands.select('green').mask()
    );
    const validPix = await getInfoAsync(validOnes.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: countScale,
      maxPixels: 1e9,
    }).values().get(0));

    if (!validPix || validPix === 0) {
      console.log(`Selected: ${sensorUsed} ${selDateStr} (cloud%: ${selCloudFrac !== null ? (selCloudFrac*100).toFixed(1) : 'NA'})`);
      console.log('Valid pixels after masking: 0');
      console.log('C2');
      return;
    }

    // Add NDWI/NDSI bands
    const imgND = computeNDWI(imgForBands, sensorUsed);

    // Water mask: NDWI > 0.3 and NDSI < 0.1 (avoid snow)
    const ndwi = imgND.select('ndwi');
    const ndsi = imgND.select('ndsi');
    const waterMask = ndwi.gt(0.3).and(ndsi.lt(0.1));

    // Water pixel count
    const waterPix = await getInfoAsync(ee.Image(1).updateMask(waterMask).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: countScale,
      maxPixels: 1e9,
    }).values().get(0));

    // If calculation invalid
    if (waterPix === null || isNaN(waterPix)) {
      console.log(`Selected: ${sensorUsed} ${selDateStr} (cloud%: ${(selCloudFrac*100).toFixed(1)})`);
      console.log('Water pixels: NaN');
      console.log('C3');
      return;
    }

    // Vectorize water to count lakes (polygons) with area threshold
    const waterImg = ee.Image(1).updateMask(waterMask).rename('water');
    const vectors = waterImg.reduceToVectors({
      reducer: ee.Reducer.countEvery(),
      geometry: region,
      scale: vecScale,
      maxPixels: 1e8,
      geometryType: 'polygon',
      labelProperty: 'label',
      eightConnected: true,
      bestEffort: true,
    });
    const lakes = vectors.filter(ee.Filter.gte('count', 1))
      .filter(ee.Filter.gt('area', -1)) // placeholder to avoid client-side
      .map(function(f) {
        return f.set('area', f.geometry().area(1));
      })
      .filter(ee.Filter.gte('area', minLakeArea));

    const lakeCount = await getInfoAsync(lakes.size());

    // Print concise evidence
    const cloudPctStr = selCloudFrac !== null ? (selCloudFrac * 100).toFixed(1) : 'NA';
    console.log(`Selected: ${sensorUsed} ${selDateStr} (cloud%: ${cloudPctStr})`);
    console.log(`Valid pixels: ${validPix}, Water pixels: ${waterPix}`);
    console.log(`Lake count (area ≥ ${Math.round(minLakeArea/1000)}k m²): ${lakeCount}`);

    // 5. Validation & Final Answer
    if (lakeCount === null || isNaN(lakeCount)) {
      console.log('C3');
      return;
    }
    if (lakeCount > 3) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (e) {
    console.log(`Error: ${e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
